// Custom validator to reject whitespace-only input
function noWhitespaceValidator() {
  return control => {
    if (control.value && typeof control.value === 'string') {
      const trimmed = control.value.trim();
      if (trimmed.length === 0) {
        return {
          whitespace: true
        };
      }
    }
    return null;
  };
}
